const allItems = $input.all().map(i => i.json);
console.log('Total items: ' + allItems.length);

const allBlogs = allItems.filter(i => i.ID_BLOG && !('STATUS' in i));
const existingRows = allItems.filter(i => 'STATUS' in i);
console.log('Blogs: ' + allBlogs.length + ' | Pipeline rows: ' + existingRows.length);

if (allBlogs.length === 0) { console.log('STOP: sin blogs.'); return []; }

const VALID = new Set(['PENDING', 'QUEUED', 'CONTENT_READY', 'READY']);
const validRows = existingRows.filter(r => VALID.has(String(r.STATUS ?? '').toUpperCase().trim()));
const junkRows  = existingRows.filter(r => { const s = String(r.STATUS ?? '').toUpperCase().trim(); return s === 'FAILED' || s === 'LOCK_TIMEOUT' || s === 'ERROR' || s === 'CANCELLED'; });
console.log('Backlog util: ' + validRows.length + ' | Basura ignorada: ' + junkRows.length);

const existingTitles = new Set(validRows.filter(r => r.TEMA_ARTICULO).map(r => r.TEMA_ARTICULO.toLowerCase().trim()));
const validByBlog = {};
validRows.forEach(r => { const id = String(r.ID_BLOG || '').trim(); if (id) validByBlog[id] = (validByBlog[id] || 0) + 1; });

const dateStr = new Date().toISOString().slice(0, 10).replace(/-/g, '');
const HIGH_RPM = ['abogad','impuest','legal','segur','accidente','multa','bienes','hipotec','salud','médic','insurance','lawyer','tax','accident'];
const isHighRpm = n => HIGH_RPM.some(k => (n || '').toLowerCase().includes(k));

const blogsNeedingTitles = allBlogs
  .filter(b => b.ID_BLOG && (validByBlog[b.ID_BLOG] || 0) < 1000)
  .sort((a, b) => { const ar = isHighRpm(a.NICHO)?0:1, br = isHighRpm(b.NICHO)?0:1; if(ar!==br) return ar-br; return (validByBlog[a.ID_BLOG]||0)-(validByBlog[b.ID_BLOG]||0); })
  .slice(0, 10);

if (blogsNeedingTitles.length === 0) { console.log('STOP: todos los blogs tienen backlog suficiente.'); return []; }
console.log('Blogs a generar: ' + blogsNeedingTitles.length);

return blogsNeedingTitles.map(blog => ({
  json: {
    blogId: blog.ID_BLOG,
    sitioUrl: blog.SITIO_URL || '',
    nicho: blog.NICHO || 'general',
    idioma: blog.IDIOMA || 'es',
    isHighRpm: isHighRpm(blog.NICHO),
    existingTitles: Array.from(existingTitles).slice(0, 30),
    titlesPerBlog: 50,
    dateStr,
    validBacklog: validByBlog[blog.ID_BLOG] || 0
  }
}));

