// chainLlm pone la respuesta en $json.text
// Los datos del blog vienen de $json también (chainLlm los pasa junto con text)
// Fallback: intentar leer desde Preparar por Blog si existe
const rawText = String($json.text || $json.output || $json.response || '');

let prev = {};
try { prev = $('Preparar por Blog').item.json || {}; } catch(e) {}
// chainLlm v1.4 también incluye los campos de entrada en $json
const blogId   = prev.blogId   || $json.blogId   || 'UNKNOWN';
const nicho    = prev.nicho    || $json.nicho    || 'general';
const dateStr  = prev.dateStr  || $json.dateStr  || new Date().toISOString().slice(0,10).replace(/-/g,'');
const existing = prev.existingTitles || $json.existingTitles || [];

console.log('Blog: ' + blogId + ' nicho=' + nicho);
console.log('rawText (' + rawText.length + ' chars): ' + rawText.substring(0, 400));

if (!rawText || rawText.trim().length < 10) throw new Error('Respuesta AI vacia');

let titlesData;
const tries = [
  () => JSON.parse(rawText.trim()),
  () => JSON.parse(rawText.replace(/^```json\s*/i,'').replace(/^```\s*/i,'').replace(/\s*```\s*$/i,'').trim()),
  () => { const m = rawText.match(/\{[\s\S]*\}/); if (!m) throw new Error('sin JSON'); return JSON.parse(m[0]); }
];
for (let i = 0; i < tries.length; i++) {
  try { titlesData = tries[i](); break; } catch(e) { console.log('parse try ' + (i+1) + ': ' + e.message); }
}
if (!titlesData) throw new Error('JSON no parseado. Raw: ' + rawText.substring(0,200));

const titles = titlesData.titles || titlesData.results || titlesData.data || [];
console.log('Titulos en respuesta: ' + titles.length);
if (titles.length === 0) throw new Error('Sin titulos. Keys: ' + Object.keys(titlesData).join(', '));

const existingSet = new Set(existing.map(t => t.toLowerCase().trim()));
const rows = [];
let skipped = 0;
for (const t of titles) {
  if (!t.title || String(t.title).trim().length < 5) continue;
  const low = String(t.title).toLowerCase().trim();
  if (existingSet.has(low)) { skipped++; continue; }
  const uid = 'TF' + dateStr + '-' + String(blogId).substring(0,6).replace(/[^a-z0-9]/gi,'') + '-' + Date.now().toString(36).slice(-4) + '-' + Math.random().toString(36).slice(2,5);
  rows.push({ ID_UNICO: uid, STATUS: 'PENDING', LOCK: 'FALSE', ID_BLOG: String(blogId), KEYWORD: String(t.keywords || t.title.split(' ').slice(0,4).join(' ')), TEMA_ARTICULO: String(t.title), ID_PARENT_SILO: '', PRIORITY: String(t.priority || 2), RETRY_COUNT: '0' });
}

console.log('A insertar: ' + rows.length + ' | Omitidos duplicados: ' + skipped);
if (rows.length === 0) { console.log('WARN: 0 titulos nuevos'); return []; }
return rows.map(r => ({ json: r }));

const items = $input.all();
if (items.length === 0) { console.log('Sin rows para insertar'); return []; }

// Orden de columnas: debe coincidir con el header de la sheet (A=ID_UNICO, B=STATUS, ...)
const values = items.map(item => {
  const r = item.json;
  return [
    String(r.ID_UNICO      || ''),
    String(r.STATUS        || 'PENDING'),
    String(r.LOCK          || 'FALSE'),
    String(r.ID_BLOG       || ''),
    String(r.KEYWORD       || ''),
    String(r.TEMA_ARTICULO || ''),
    String(r.ID_PARENT_SILO|| ''),
    String(r.PRIORITY      || '2'),
    String(r.RETRY_COUNT   || '0')
  ];
});

console.log('Batch listo: ' + values.length + ' rows para API Sheets v4');
return [{ json: { values, count: values.length } }];

const allItems = $input.all().map(i => i.json);
const toArchive = allItems.filter(r => { const s = String(r.STATUS??'').toUpperCase().trim(); const retry = parseInt(String(r.RETRY_COUNT||'0'),10); return (s==='FAILED'||s==='LOCK_TIMEOUT') && retry>2 && r.ID_UNICO; });
if (toArchive.length === 0) { console.log('Sin huerfonos.'); return []; }
console.log('Archivando: ' + toArchive.length);
return toArchive.map(r => ({ json: { ID_UNICO: r.ID_UNICO, STATUS: 'ARCHIVED' } }));
